# The meet-in-the-middle of measure.py, run for real on m = 6, K = 2^24 (split 467 479 487 | 491 499 503): the lists
# L_A = {x_A : S_A >= tA}, L_B = {x_B : S_B >= tB} generated by enumeration, lifted by the CRT, and matched with a sort and range
# queries on k = u_A + u_B (mod P) < K. Checks that the matches are exactly the window's members with S_A >= tA and S_B >= tB, and
# that their list sizes are the convolution counts measure.py charges.
#   python3 mitm_run.py [tA tB]
import sys, math, time
import numpy as np
from toy import setup

def side_list(W, primes, tau):
    """all class vectors (a_1, .., a_j) with sum w_i(a_i) >= tau, j = 3, by a sorted pair table and prefixes."""
    w1, w2, w3 = W; s1, s2, s3 = primes
    w23 = (w2[:, None] + w3[None, :]).ravel(); order = np.argsort(-w23, kind="stable"); w23s = w23[order]
    out = []
    for a1 in range(s1):
        need = tau - int(w1[a1]); cnt = int(np.searchsorted(-w23s, -need, side="right"))   # w23s >= need
        if cnt == 0: continue
        idx = order[:cnt]; out.append(np.stack([np.full(cnt, a1), idx // s3, idx % s3], 1))
    return np.concatenate(out) if out else np.zeros((0, 3), np.int64)

def crt3(V, primes):
    PA = math.prod(primes); e = [(PA // s) * pow(PA // s, -1, s) % PA for s in primes]
    r = np.zeros(len(V), np.int64)
    for i in range(3): r = (r + V[:, i].astype(np.int64) * e[i]) % PA
    return r

if __name__ == "__main__":
    tA, tB = (int(sys.argv[1]), int(sys.argv[2])) if len(sys.argv) > 2 else (18, 18)
    K = 2 ** 24; T = setup("../covers/q200000_m89.txt", 6, K); later, W = T["later"], T["W"]
    A, B = later[:3], later[3:]; PA, PB = math.prod(A), math.prod(B); P = PA * PB
    t0 = time.time()
    LA = side_list(W[:3], A, tA); LB = side_list(W[3:], B, tB)
    rA, rB = crt3(LA, A), crt3(LB, B)
    eA, eB = pow(PB % PA, -1, PA), pow(PA % PB, -1, PB)
    uA = PB * ((rA * eA) % PA); uB = PB * 0 + PA * ((rB * eB) % PB)          # k = u_A + u_B (mod P)
    o = np.argsort(uB); uBs = uB[o]
    ks = []
    # u_B in [0, K - u_A) when u_A < K, and in [P - u_A, P - u_A + K)
    lo1 = np.zeros_like(uA); hi1 = np.where(uA < K, K - uA, 0)
    lo2 = P - uA; hi2 = P - uA + K
    for lo, hi in ((lo1, hi1), (lo2, hi2)):
        i0 = np.searchsorted(uBs, lo, "left"); i1 = np.searchsorted(uBs, hi, "left")
        for j in np.nonzero(i1 > i0)[0]:
            for b in uBs[i0[j]:i1[j]]: ks.append(int((int(uA[j]) + int(b)) % P))
    ks = np.array(sorted(set(ks)), dtype=np.int64); dt = time.time() - t0
    # the window's truth
    k = np.arange(K, dtype=np.int64)
    SA = sum(w[k % s] for s, w in zip(A, W[:3])); SB = sum(w[k % s] for s, w in zip(B, W[3:]))
    truth = np.nonzero((SA >= tA) & (SB >= tB))[0]
    print(f"tA = {tA}, tB = {tB}: |L_A| = {len(LA):,}, |L_B| = {len(LB):,}; matches {len(ks):,} (all < K: {bool((ks < K).all())}); "
          f"window members with S_A >= tA and S_B >= tB: {len(truth):,}; identical: {np.array_equal(ks, truth)}; "
          f"scores of the matches >= {tA + tB}: {bool(((SA + SB)[ks] >= tA + tB).all())}; {dt:.1f} s")
    # the counts measure.py charges
    from measure import conv_hist, suffix
    print(f"convolution counts: |L_A| {int(suffix(conv_hist(W[:3]))[tA]):,}, |L_B| {int(suffix(conv_hist(W[3:]))[tB]):,}")
